// Validate incoming navigation request
const data = items[0].json;

const required = ['origin', 'destination'];
const missing = required.filter(k => !data[k]);
if (missing.length > 0) {
  return [{ json: { error: 'Missing required fields: ' + missing.join(', '), status: 'error' } }];
}

// Validate origin/destination have lat/lng
const forLoc = ['origin', 'destination'];
for (const loc of forLoc) {
  if (typeof data[loc].lat !== 'number' || typeof data[loc].lng !== 'number') {
    return [{ json: { error: loc + ' must have numeric lat and lng', status: 'error' } }];
  }
}

// Generate session ID
const sessionId = 'nav_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);

return [{
  json: {
    session_id: sessionId,
    origin: data.origin,
    destination: data.destination,
    destination_name: data.destination.name || data.destination.address || 'Destination',
    status: 'active',
    created_at: Date.now(),
    updated_at: Date.now(),
    navigation_valid: true,
  }
}];

// Parse Google Directions API response and extract route steps
const data = items[0].json;

if (data.status !== 'OK') {
  return [{
    json: {
      error: 'Directions API error: ' + data.status,
      status: 'failed',
      has_route: false,
    }
  }];
}

const routes = data.routes || [];
if (routes.length === 0) {
  return [{
    json: {
      error: 'No routes found',
      status: 'failed',
      has_route: false,
    }
  }];
}

// Take first route
const route = routes[0];
const steps = (route.legs || []).flatMap(leg =>
  (leg.steps || []).map((step, i) => ({
    instruction: step.html_instructions || step.instructions || 'Continue',
    distance_m: Math.round((step.distance ? step.distance.value : 0) || 0),
    duration_s: Math.round((step.duration ? step.duration.value : 0) || 0),
    turn: infer_turn(step),
    step_number: i,
  }))
);

function infer_turn(step) {
  const html = (step.html_instructions || '').toLowerCase();
  if (html.includes('turn left')) return 'left';
  if (html.includes('turn right')) return 'right';
  if (html.includes('u-turn')) return 'u-turn';
  if (html.includes('slightly left')) return 'slightly_left';
  if (html.includes('slightly right')) return 'slightly_right';
  if (html.includes('straight')) return 'straight';
  return null;
}

return [{
  json: {
    has_route: true,
    total_distance_m: Math.round(route.legs[0].distance.value || 0),
    total_duration_s: Math.round(route.legs[0].duration.value || 0),
    steps: steps,
    current_step_index: 0,
    status: 'active',
  }
}];
